import { type App, Modal } from 'obsidian';
import type { RecordSummary } from './backlog-record';
import type { CreationResult } from './creation';
import { describeWarning, type EmbedWarning } from './embeds';
import type { Preview, StoryView, Verdict } from './preview';

/**
 * Preview window. SECURITY: every string coming from Refinr (generated by a language model) is inserted as plain text
 * with `createEl({ text })` / `setText` — never as HTML or rendered Markdown (checked by `tests/plain-text.test.ts`).
 */
export interface DoneState {
	kind: 'done';
	preview: Preview;
	chars: number;
	warnings: EmbedWarning[];
	/** Name of Refinr's tracker (`GET /tracker`); null when unknown (no creation then). */
	tracker: string | null;
	defaultProject: string;
}

/** Outcome of writing the `refinr` property; `yaml` is offered to copy when it could not be written. */
export interface FrontmatterOutcome {
	ok: boolean;
	message: string;
	yaml: string | null;
}

export type PreviewState =
	| { kind: 'reading' }
	| { kind: 'analyzing'; chars: number; limit: number; warnings: EmbedWarning[] }
	| { kind: 'error'; message: string; warnings: EmbedWarning[] }
	| DoneState
	| { kind: 'confirm'; base: DoneState; existing: RecordSummary | null }
	| { kind: 'creating'; base: DoneState; project: string }
	| { kind: 'created'; base: DoneState; result: CreationResult; frontmatter: FrontmatterOutcome }
	| { kind: 'create-failed'; base: DoneState; message: string; unknown: boolean; frontmatter: FrontmatterOutcome | null };

/** Actions of the window, carried out by the plugin. */
export interface PreviewHandlers {
	/** Summary of the note's current `refinr` property, read when the confirmation opens. */
	existingRecord(): RecordSummary | null;
	/** Starts the creation (the window is already in the `creating` state). */
	create(base: DoneState, projectKey: string): void;
	copy(text: string): void;
}

const VERDICT_LABELS: Record<Verdict, string> = {
	'ai-ready': 'ai-ready',
	'validation-necessaire': 'validation-necessaire',
	unknown: 'no verdict',
};

export class PreviewModal extends Modal {
	private state: PreviewState = { kind: 'reading' };
	private shown = false;

	constructor(
		app: App,
		private readonly noteName: string,
		private readonly handlers: PreviewHandlers,
	) {
		super(app);
	}

	get isShown(): boolean {
		return this.shown;
	}

	get current(): PreviewState {
		return this.state;
	}

	setState(state: PreviewState): void {
		this.state = state;
		if (this.shown) {
			this.render();
		}
	}

	onOpen(): void {
		this.shown = true;
		this.render();
	}

	onClose(): void {
		this.shown = false;
		this.contentEl.empty();
	}

	private render(): void {
		const el = this.contentEl;
		el.empty();
		el.addClass('refinr-preview');
		this.setTitle(`Refinr preview: ${this.noteName}`);
		const state = this.state;
		switch (state.kind) {
			case 'reading':
				el.createEl('p', { text: 'Reading the note and its embeds…' });
				return;
			case 'analyzing':
				renderWarnings(el, state.warnings);
				el.createEl('p', {
					text: `Refinr is analyzing ${state.chars.toLocaleString('en-US')} characters (limit ${state.limit.toLocaleString('en-US')}).`,
				});
				el.createEl('p', {
					cls: 'refinr-muted',
					text: 'This can take several minutes. You can close this window: a notice will tell you when the preview is ready.',
				});
				return;
			case 'error':
				renderWarnings(el, state.warnings);
				el.createEl('p', { cls: 'refinr-error', text: state.message });
				return;
			case 'done':
				renderWarnings(el, state.warnings);
				renderPreview(el, state.preview, state.chars);
				this.renderCreateButton(el, state);
				return;
			case 'confirm':
				this.renderConfirm(el, state.base, state.existing);
				return;
			case 'creating':
				el.createEl('p', {
					text: `Creating ${countIssues(state.base.preview)} issue(s) in ${state.base.tracker ?? 'the tracker'}` +
						(state.project === '' ? '' : ` (project ${state.project})`) + '…',
				});
				el.createEl('p', {
					cls: 'refinr-muted',
					text: 'Refinr computes the verdicts again, then creates each issue: this can take several minutes. You can close this window.',
				});
				return;
			case 'created':
				renderCreated(el, state.base, state.result);
				this.renderFrontmatter(el, state.frontmatter);
				return;
			case 'create-failed':
				el.createEl('p', { cls: state.unknown ? 'refinr-warning' : 'refinr-error', text: state.message });
				if (state.frontmatter !== null) {
					this.renderFrontmatter(el, state.frontmatter);
				}
				return;
		}
	}

	private renderCreateButton(el: HTMLElement, state: DoneState): void {
		if (state.preview.epics.length === 0) {
			return;
		}
		const footer = el.createDiv({ cls: 'refinr-footer' });
		if (state.tracker === null) {
			footer.createEl('p', { cls: 'refinr-muted', text: 'The tracker of Refinr is unknown: run Test connection, then analyze again to create the issues.' });
			return;
		}
		const button = footer.createEl('button', { cls: 'mod-cta', text: `Create in ${state.tracker}` });
		button.addEventListener('click', () => {
			this.setState({ kind: 'confirm', base: state, existing: this.handlers.existingRecord() });
		});
	}

	private renderConfirm(el: HTMLElement, base: DoneState, existing: RecordSummary | null): void {
		const t = base.preview.totals;
		el.createEl('h3', { text: `Create in ${base.tracker ?? 'the tracker'}` });
		el.createEl('p', { text: `${t.epics} epic(s), ${t.stories} story(ies), ${t.tasks} sub-task(s) will be created.` });
		el.createEl('p', {
			cls: 'refinr-muted',
			text: 'Refinr computes the verdicts again before creating: they may differ from this preview.',
		});
		if (existing !== null) {
			const box = el.createDiv({ cls: 'refinr-warnings' });
			box.createEl('p', {
				cls: 'refinr-warnings-title',
				text: 'This note already has a Refinr backlog.',
			});
			box.createEl('p', {
				text:
					`Created ${existing.created === '' ? '(date unknown)' : existing.created} in ${existing.tracker === '' ? '(tracker unknown)' : existing.tracker}` +
					`, ${existing.stories} story(ies), status ${existing.status === '' ? 'unknown' : existing.status}` +
					(existing.previous > 0 ? `, ${existing.previous} earlier creation(s)` : '') + '.',
			});
			box.createEl('p', {
				text: 'Creating again creates new issues in the tracker. The current entry is kept in refinr.history; nothing is overwritten.',
			});
		}
		const projectRow = el.createDiv({ cls: 'refinr-field' });
		projectRow.createEl('label', { text: 'Project key', attr: { for: 'refinr-project-key' } });
		const project = projectRow.createEl('input', {
			attr: { id: 'refinr-project-key', type: 'text', placeholder: "Refinr's default project" },
		});
		project.value = base.defaultProject;
		const buttons = el.createDiv({ cls: 'refinr-footer' });
		const cancel = buttons.createEl('button', { text: 'Cancel' });
		cancel.addEventListener('click', () => this.setState(base));
		const confirm = buttons.createEl('button', { cls: 'mod-cta', text: existing === null ? 'Create' : 'Create again' });
		confirm.addEventListener('click', () => {
			// One click only: the state changes before the request is sent, the buttons disappear with it.
			confirm.disabled = true;
			cancel.disabled = true;
			const projectKey = project.value.trim();
			this.setState({ kind: 'creating', base, project: projectKey });
			this.handlers.create(base, projectKey);
		});
	}

	private renderFrontmatter(el: HTMLElement, outcome: FrontmatterOutcome): void {
		el.createEl('p', { cls: outcome.ok ? 'refinr-muted' : 'refinr-warning', text: outcome.message });
		const yaml = outcome.yaml;
		if (yaml !== null) {
			const button = el.createEl('button', { text: 'Copy as YAML' });
			button.addEventListener('click', () => this.handlers.copy(yaml));
		}
	}
}

function countIssues(preview: Preview): number {
	return preview.totals.epics + preview.totals.stories + preview.totals.tasks;
}

/** Creation result: what was created (keys, links, verdicts computed again) and what failed, Refinr's reasons as-is. */
function renderCreated(el: HTMLElement, base: DoneState, result: CreationResult): void {
	const byType = (type: string) => result.created.filter((issue) => issue.type === type).length;
	el.createEl('p', {
		cls: 'refinr-totals',
		text:
			`Created ${result.created.length} issue(s) in ${base.tracker ?? 'the tracker'}: ${byType('epic')} epic(s), ` +
			`${byType('story')} story(ies), ${byType('subtask')} sub-task(s)` +
			(result.failed.length > 0 ? `; ${result.failed.length} not created.` : '.'),
	});
	const previewVerdicts = uniqueVerdicts(base.preview);
	if (result.stories.length > 0) {
		const list = el.createEl('ul', { cls: 'refinr-created' });
		for (const story of result.stories) {
			const item = list.createEl('li');
			if (story.url !== null) {
				item.createEl('a', { text: story.key, href: story.url });
			} else {
				item.createSpan({ text: story.key });
			}
			item.createSpan({ text: ` ${story.title} ` });
			if (story.fallback) {
				item.createSpan({ cls: 'refinr-verdict refinr-verdict-unknown', text: 'no verdict' });
				item.createSpan({ cls: 'refinr-warning', text: ' AI unavailable, human validation required' });
				continue;
			}
			item.createSpan({ cls: `refinr-verdict refinr-verdict-${story.verdict}`, text: story.verdict });
			const before = previewVerdicts.get(story.title);
			if (before !== undefined && before !== story.verdict) {
				item.createSpan({ cls: 'refinr-muted', text: ` (preview: ${VERDICT_LABELS[before]})` });
			}
		}
	}
	if (result.failed.length > 0) {
		const box = el.createDiv({ cls: 'refinr-warnings' });
		box.createEl('p', { cls: 'refinr-warnings-title', text: `${result.failed.length} item(s) not created` });
		const list = box.createEl('ul');
		for (const issue of result.failed) {
			list.createEl('li', { text: `${issue.type} "${issue.title}": ${issue.reason}` });
		}
	}
}

/** Preview verdict by story title, for titles that appear once (duplicates are not compared). */
function uniqueVerdicts(preview: Preview): Map<string, Verdict> {
	const counts = new Map<string, number>();
	const verdicts = new Map<string, Verdict>();
	for (const story of preview.epics.flatMap((epic) => epic.stories)) {
		counts.set(story.title, (counts.get(story.title) ?? 0) + 1);
		verdicts.set(story.title, story.verdict);
	}
	for (const [title, count] of counts) {
		if (count > 1) {
			verdicts.delete(title);
		}
	}
	return verdicts;
}

/** Warnings change what was sent: shown first, in a visible box, with the characters left out when known. */
function renderWarnings(el: HTMLElement, warnings: EmbedWarning[]): void {
	if (warnings.length === 0) {
		return;
	}
	const box = el.createDiv({ cls: 'refinr-warnings' });
	const dropped = warnings.reduce((sum, warning) => sum + (warning.droppedChars ?? 0), 0);
	box.createEl('p', {
		cls: 'refinr-warnings-title',
		text:
			`The text sent differs from the note: ${warnings.length} embed problem(s)` +
			(dropped > 0 ? `, ${dropped.toLocaleString('en-US')} characters left out.` : '.'),
	});
	const items = box.createEl('ul');
	for (const warning of warnings) {
		items.createEl('li', { text: describeWarning(warning) });
	}
}

function renderPreview(el: HTMLElement, preview: Preview, chars: number): void {
	const t = preview.totals;
	el.createEl('p', {
		cls: 'refinr-totals',
		text:
			`${t.epics} epic(s) · ${t.stories} story(ies) · ${t.tasks} sub-task(s) · ` +
			`${t.aiReady} ai-ready · ${t.needsValidation} validation-necessaire` +
			(t.noVerdict > 0 ? ` · ${t.noVerdict} without verdict` : '') +
			` — from ${chars.toLocaleString('en-US')} characters.`,
	});
	if (preview.epics.length === 0) {
		el.createEl('p', { text: 'Refinr found nothing to turn into a backlog in this note.' });
		return;
	}
	for (const epic of preview.epics) {
		const epicEl = el.createDiv({ cls: 'refinr-epic' });
		epicEl.createEl('h3', { text: epic.name === '' ? 'Untitled epic' : epic.name });
		addMeta(epicEl, epic.priority, epic.labels);
		addText(epicEl, epic.description, 'refinr-description');
		for (const story of epic.stories) {
			renderStory(epicEl, story);
		}
	}
}

function renderStory(parent: HTMLElement, story: StoryView): void {
	const details = parent.createEl('details', { cls: 'refinr-story' });
	const summary = details.createEl('summary');
	summary.createSpan({ cls: 'refinr-story-title', text: story.title === '' ? 'Untitled story' : story.title });
	summary.createSpan({ cls: `refinr-verdict refinr-verdict-${story.verdict}`, text: VERDICT_LABELS[story.verdict] });
	if (story.storyPoints !== null) {
		summary.createSpan({ cls: 'refinr-points', text: `${story.storyPoints} pts` });
	}

	if (story.asA !== '' || story.iWant !== '' || story.soThat !== '') {
		addText(details, `As ${story.asA}, I want ${story.iWant}, so that ${story.soThat}.`, 'refinr-user-story');
	}
	addMeta(details, story.priority, story.labels);
	addText(details, story.description, 'refinr-description');
	if (story.verdictReason !== '') {
		addText(details, `Verdict: ${story.verdictReason}`, 'refinr-verdict-reason');
	}
	if (story.acceptanceCriteria.length > 0) {
		details.createEl('p', { cls: 'refinr-subheading', text: 'Acceptance criteria' });
		const list = details.createEl('ul');
		for (const criterion of story.acceptanceCriteria) {
			list.createEl('li', { text: criterion });
		}
	}
	if (story.tasks.length > 0) {
		details.createEl('p', { cls: 'refinr-subheading', text: 'Sub-tasks' });
		const list = details.createEl('ul');
		for (const task of story.tasks) {
			const item = list.createEl('li');
			item.createSpan({ text: task.title === '' ? 'Untitled sub-task' : task.title });
			if (task.estimatedHours !== null) {
				item.createSpan({ cls: 'refinr-muted', text: ` (${task.estimatedHours} h)` });
			}
			addText(item, task.description, 'refinr-description');
		}
	}
}

function addMeta(parent: HTMLElement, priority: string, labels: string[]): void {
	const parts = [priority === '' ? '' : `Priority: ${priority}`, labels.length === 0 ? '' : `Labels: ${labels.join(', ')}`];
	addText(parent, parts.filter((part) => part !== '').join(' · '), 'refinr-muted');
}

function addText(parent: HTMLElement, text: string, cls: string): void {
	if (text !== '') {
		parent.createEl('p', { cls, text });
	}
}
